using JTradeERP.Application.Common.Persistence;using JTradeERP.Application.Features.Billing.NumberSeries.Common;using MediatR;namespace JTradeERP.Application.Features.Billing.NumberSeries.GetNumberSeries;public sealed class GetNumberSeriesHandler(IApplicationDbContext db):IRequestHandler<GetNumberSeriesQuery,GetNumberSeriesResponse>{public Task<GetNumberSeriesResponse> Handle(GetNumberSeriesQuery r,CancellationToken ct)=>Task.FromResult(new GetNumberSeriesResponse(db.NumberSeries.OrderBy(x=>x.DocumentType).Select(x=>new NumberSeriesResponse(x.Id,x.DocumentType,x.Prefix,x.NextNumber,x.Padding)).ToList()));}
